+func oq3EnvelopeLeaks(c oq3Capture) []string {
+	out := oq3Leaks(c.Path)
+	if c.Query != "" {
+		out = append(out, oq3Leaks(c.Query)...)
+		if q, err := url.ParseQuery(c.Query); err == nil {
+			for k, vs := range q {
+				out = append(out, oq3Leaks(k)...)
+				for _, v := range vs {
