+					}
+				}
+			}
+		}
+		if last != text {
+			t.Fatalf("idle control: the turn after the busy command sent %q, want %q", last, text)
+		}
+		if !oq3WaitFor(30*time.Second, func() bool { return d.completedLabel(label) >= 1 }) || !term.idle(30*time.Second) {
