 66	func oq3NewRun(t *testing.T, sc oq3Scenario, d *oq3Daemon, s *oq3Sandbox) *oq3Run {
 67		return &oq3Run{t: t, sc: sc, d: d, s: s, convIDs: map[string]string{}, async: map[string]chan asyncResult{},
 68			marks: map[string]int{}, marksLabel: map[string]string{}}
 69	}
