 76	func oq3Label(sc string, i int, op string) string { return fmt.Sprintf("%s/%02d/%s", sc, i, op) }
 77	
 78	func (r *oq3Run) event(i int, st oq3Step, verdict string, outcome any) {
 79		r.events = append(r.events, oq3Event{Scenario: r.sc.ID, Step: i, Op: st.Op, Class: st.Class, Label: oq3Label(r.sc.ID, i, st.Op),
 80			Trial: st.Trial, Verdict: verdict, Outcome: outcome, At: time.Now().Format(time.RFC3339Nano)})
 81		if verdict == "harness-failed" {
 82			r.invalid = append(r.invalid, fmt.Sprintf("%s step %d %s: %v", r.sc.ID, i, st.Op, outcome))
 83		}
 84	}
 85	
 86	// execute runs every step. A harness failure stops the scenario (later steps are recorded as not
 87	// run) and makes the run invalid; it is never scored as a delivery defect.
 88	func (r *oq3Run) execute() {
 89		for i, st := range r.sc.Steps {
 90			label := oq3Label(r.sc.ID, i, st.Op)
 91			switch st.Op {
 92			case "terminal-await":
 93				// Requests caused while a held turn completes (its tool continuations) belong to that
 94				// turn, so its label stays active.
 95				r.d.setLabel(r.heldLabel("terminal"))
 96			case "desktop-await":
 97				r.d.setLabel(r.heldLabel(st.Args["conv"]))
 98			default:
 99				r.d.setLabel(label)
100			}
101			if len(r.invalid) > 0 {
102				r.event(i, st, "not-run", "an earlier harness failure stopped this scenario")
103				continue
104			}
105			func() {
106				defer func() {
107					if p := recover(); p != nil {
108						r.event(i, st, "harness-failed", fmt.Sprint(p))
109					}
110				}()
111				r.step(i, st, label)
112			}()
113		}
114		if r.term != nil {
115			r.term.kill()
116		}
117		if r.desk != nil {
118			_ = r.desk.cmd.Process.Kill()
119		}
120	}
121	
122	func (r *oq3Run) harnessFail(format string, a ...any) {
123		panic(fmt.Sprintf(format, a...))
124	}
