366	// Terminal turns and commands.
367	
368	// terminalStartWithoutCapability starts a session against a daemon without chat.admission.v1 (review
369	// round 2, finding 6). A12 (blueprint §6.3) and §8 require no carrier-bearing request and a
370	// context_unavailable report naming the daemon's version; nothing requires the check to wait for a
371	// preload. So the session may preload and go idle (the unchanged candidate does), or refuse at
372	// start-up, exiting or staying open. A refusal is recognised only by its report: the daemon's version
373	// on screen. A session that ends at start-up without it is a harness failure, never a refusal.
374	func (r *oq3Run) terminalStartWithoutCapability(i int, st oq3Step, preloaded func() bool) {
375		reported := func() bool { return r.term.screenContainsJoined(oq3NoAdmissionVersion) }
376		if !oq3WaitFor(30*time.Second, func() bool { return preloaded() || r.term.hasExited() || reported() }) {
377			r.harnessFail("terminal session neither preloaded, reported the missing capability nor exited; screen tail %q", tail(r.term.screen(), 1500))
378		}
379		// A report is often the last thing a refusing process prints before it exits.
380		if reported() && !r.term.hasExited() {
381			oq3WaitFor(2*time.Second, r.term.hasExited)
382		}
383		exitedWithReport := func() {
384			// The output of a process that has just exited may still be draining from the terminal.
385			if !oq3WaitFor(3*time.Second, reported) {
386				r.harnessFail("terminal session exited at start-up without reporting the daemon's version %s; screen tail %q", oq3NoAdmissionVersion, tail(r.term.screen(), 1500))
387			}
388			r.termRefusedAtStart = true
389			r.event(i, st, "refused-at-start", map[string]any{"session": r.termN, "exited": true, "preloaded": preloaded(), "screen_tail": tail(r.term.screen(), 600)})
390		}
391		if r.term.hasExited() {
392			exitedWithReport()
393			return
394		}
395		// Still running: whether it preloaded or reported first, it must reach an idle chat, which also
396		// settles any preload that follows a report.
397		if !r.term.idle(30 * time.Second) {
398			if r.term.hasExited() {
399				exitedWithReport()
400				return
401			}
402			r.harnessFail("terminal never proved idle after the session started without the capability; screen tail %q", tail(r.term.screen(), 800))
403		}
404		if !preloaded() && reported() {
405			r.termRefusedAtStart = true
406			r.event(i, st, "refused-at-start", map[string]any{"session": r.termN, "exited": false, "screen_tail": tail(r.term.screen(), 600)})
407			return
408		}
409		r.event(i, st, "done", map[string]any{"session": r.termN, "preloaded": preloaded(), "reported": reported()})
410	}
411	
412	func (r *oq3Run) terminalTurn(i int, st oq3Step, label string) {
413		if r.termRefusedAtStart && r.term.hasExited() {
414			// The session refused at start-up and has ended: nothing can be typed, and no request under
415			// this step was sent. Scored by the step's class (a refusal held as required).
416			r.event(i, st, "no-request", map[string]any{"session": "refused at start-up; the process has exited"})
417			return
418		}
419		rounds, _ := strconv.Atoi(st.Args["tool_rounds"])
420		if rounds > 0 {
421			r.d.setToolRounds(label, rounds)
422		}
423		if st.Args["auto_compact"] == "1" {
424			r.d.reportPromptEval(label, 30000)
425		}
426		mark := r.term.rawLen()
427		if st.Args["hold"] == "1" {
428			r.d.hold(label)
429			r.marksLabel["terminal"] = label
430			r.marks["terminal"] = mark
431		}
432		r.term.typeLine(st.Prompt)
433		if !oq3WaitFor(30*time.Second, func() bool { return r.d.countLabel("POST", "/api/chat", label) >= 1 }) {
434			// No request reached the daemon: recorded, and scored by the step's class (a missing
435			// required delivery, or a refusal held as required).
436			r.mustIdle("after a turn that sent no request")
437			r.event(i, st, "no-request", map[string]any{"screen_tail": tail(r.term.screen(), 1200)})
438			return
439		}
440		if st.Args["hold"] == "1" {
441			r.marks["terminal-rounds"] = rounds
442			r.event(i, st, "dispatched-held", nil)
443			return
444		}
445		r.finishTerminalTurn(label, rounds, st.Summarisers, mark)
446		r.event(i, st, "done", nil)
447	}
448	
449	// finishTerminalTurn approves each declared tool round, then waits until every response under the
450	// label has been fully written by the daemon (review finding 8) and the chat has proved it is idle
451	// (review round 2, finding 5): the daemon finishing and the screen going quiet do not show that the
452	// chat's run has ended.
453	func (r *oq3Run) finishTerminalTurn(label string, rounds, summarisers, mark int) {
454		for k := 0; k < rounds; k++ {
455			approvalMark := mark
456			if !oq3WaitFor(30*time.Second, func() bool { return r.term.screenContainsAfter(approvalMark, "Approve once") }) {
457				r.harnessFail("tool round %d: approval prompt never appeared; screen tail %q", k+1, tail(r.term.screen(), 1500))
458			}
459			want := r.d.countLabel("POST", "/api/chat", label) + 1
460			mark = r.term.rawLen()
461			r.term.key("1")
462			if !oq3WaitFor(30*time.Second, func() bool { return r.d.countLabel("POST", "/api/chat", label) >= want }) {
463				r.harnessFail("tool round %d: continuation never reached the daemon", k+1)
464			}
465		}
466		if !oq3WaitFor(30*time.Second, func() bool {
467			n := r.d.countLabel("POST", "/api/chat", label)
468			return r.d.countSummaries(label) >= summarisers && r.d.completedLabel(label) >= n
469		}) {
470			r.harnessFail("responses under %s never completed (%d requests, %d completed, %d summaries)", label,
471				r.d.countLabel("POST", "/api/chat", label), r.d.completedLabel(label), r.d.countSummaries(label))
472		}
473		r.mustIdle("after the turn completed")
474	}
