 451	// (review round 2, finding 5): the daemon finishing and the screen going quiet do not show that the
 452	// chat's run has ended.
 453	func (r *oq3Run) finishTerminalTurn(label string, rounds, summarisers, mark int) {
 454		for k := 0; k < rounds; k++ {
 455			approvalMark := mark
 456			if !oq3WaitFor(30*time.Second, func() bool { return r.term.screenContainsAfter(approvalMark, "Approve once") }) {
 457				r.harnessFail("tool round %d: approval prompt never appeared; screen tail %q", k+1, tail(r.term.screen(), 1500))
 458			}
 459			want := r.d.countLabel("POST", "/api/chat", label) + 1
 460			mark = r.term.rawLen()
 461			r.term.key("1")
 462			if !oq3WaitFor(30*time.Second, func() bool { return r.d.countLabel("POST", "/api/chat", label) >= want }) {
 463				r.harnessFail("tool round %d: continuation never reached the daemon", k+1)
 464			}
 465		}
 466		if !oq3WaitFor(30*time.Second, func() bool {
 467			n := r.d.countLabel("POST", "/api/chat", label)
 468			return r.d.countSummaries(label) >= summarisers && r.d.completedLabel(label) >= n
 469		}) {
 470			r.harnessFail("responses under %s never completed (%d requests, %d completed, %d summaries)", label,
 471				r.d.countLabel("POST", "/api/chat", label), r.d.completedLabel(label), r.d.countSummaries(label))
 472		}
 473		r.mustIdle("after the turn completed")
 474	}
