 476	// mustQuiet waits for the terminal to stop producing output; a timeout is a harness failure, never
 477	// a reason to advance (review finding 8). It paces keystrokes into a menu or picker; it is not the
 478	// proof that a turn has ended, which is mustIdle.
 479	func (r *oq3Run) mustQuiet(when string) {
 480		if !r.term.quiet(600*time.Millisecond, 20*time.Second) {
 481			r.harnessFail("terminal did not go quiet %s; screen tail %q", when, tail(r.term.screen(), 800))
 482		}
 483	}
