 485	// mustIdle requires the chat's own proof that it is idle (oq3Terminal.idle); a timeout is a harness
 486	// failure, never a reason to advance (review round 2, finding 5).
 487	func (r *oq3Run) mustIdle(when string) {
 488		if !r.term.idle(30 * time.Second) {
 489			r.harnessFail("terminal never proved idle %s; screen tail %q", when, tail(r.term.screen(), 800))
 490		}
 491	}
