 493	func (r *oq3Run) terminalSlash(i int, st oq3Step, label string) {
 494		cmd := st.Args["cmd"]
 495		mark := r.term.rawLen()
 496		if pick := st.Args["pick"]; pick != "" {
 497			r.term.typeLine(cmd)
 498			if !oq3WaitFor(15*time.Second, func() bool { return r.term.screenContainsAfter(mark, pick) }) {
 499				r.harnessFail("model picker never listed %s; screen tail %q", pick, tail(r.term.screen(), 1500))
 500			}
 501			// Every wait is checked (review round 2, finding 5); the chat must then prove it is idle, so
 502			// the next step cannot start while the switch is still being applied.
 503			r.mustQuiet("while the model picker lists " + pick)
 504			r.term.key(pick)
 505			r.mustQuiet("after filtering the model picker for " + pick)
 506			r.term.key("\r")
 507			r.mustIdle("after picking " + pick)
 508			r.event(i, st, "done", map[string]any{"picked": pick, "screen_tail": tail(r.term.screen(), 600)})
 509			return
 510		}
 511		r.term.typeLine(cmd)
 512		if st.Class == "required-refusal" {
 513			// Sent while a held turn runs: the screen only animates, so nothing on it can show the
 514			// refusal. Its effect is judged by the held turn's own continuation, which must keep the
 515			// old revision (review finding 1). No wait: the turn is still running.
 516			r.event(i, st, "sent-while-running", nil)
 517			return
 518		}
 519		if st.Summarisers > 0 {
 520			if !oq3WaitFor(30*time.Second, func() bool {
 521				return r.d.countSummaries(label) >= st.Summarisers && r.d.completedLabel(label) >= r.d.countLabel("POST", "/api/chat", label)
 522			}) {
 523				r.mustIdle("after a compaction that did not complete")
 524				r.event(i, st, "fail", map[string]any{"summarisers_seen": r.d.countSummaries(label), "screen_tail": tail(r.term.screen(), 1200)})
 525				return
 526			}
 527		}
 528		r.mustIdle("after " + cmd)
 529		unknown := r.term.screenContainsAfter(mark, "Unknown command") || r.term.screenContainsAfter(mark, "usage: ")
 530		verdict := "done"
 531		switch {
 532		case unknown && strings.HasPrefix(cmd, "/instructions"):
 533			verdict = "absent"
 534		case unknown:
 535			// An existing command that printed an error or its usage did not do what the step declares.
 536			r.harnessFail("%s was rejected by the terminal; screen tail %q", cmd, tail(oq3ANSI.ReplaceAllString(r.term.rawSince(mark), ""), 600))
 537		case strings.HasPrefix(cmd, "/instructions"):
 538			// No error was printed. The blueprint (§7) names no success output, so the screen cannot
 539			// show success; the delivery after this step decides (review finding 1).
 540			verdict = "no-error-seen"
 541		}
 542		r.event(i, st, verdict, map[string]any{"screen_tail": tail(oq3ANSI.ReplaceAllString(r.term.rawSince(mark), ""), 600)})
 543	}
