454	// waitFor polls until cond is true or the deadline passes; it never sleeps a fixed interval blindly.
455	func oq3WaitFor(timeout time.Duration, cond func() bool) bool {
456		deadline := time.Now().Add(timeout)
457		for time.Now().Before(deadline) {
458			if cond() {
459				return true
460			}
461			time.Sleep(20 * time.Millisecond)
462		}
463		return cond()
464	}
