466	func (d *oq3Daemon) record(r *http.Request, body []byte, kind string) {
467		d.mu.Lock()
468		defer d.mu.Unlock()
469		d.seq++
470		c := oq3Capture{Seq: d.seq, At: time.Now().Format(time.RFC3339Nano), Method: r.Method, Path: r.URL.Path, Label: d.label, Response: kind,
471			Query: r.URL.RawQuery}
472		if len(r.Header) > 0 {
473			c.Headers = map[string][]string{}
474			for name, vals := range r.Header {
475				for _, v := range vals {
476					for _, l := range oq3Leaks(name + ": " + v) {
477						c.HeaderLeaks = append(c.HeaderLeaks, name+" "+l)
478					}
479					if oq3CredentialHeader(name) {
480						v = fmt.Sprintf("<redacted %d bytes>", len(v))
481					}
482					c.Headers[name] = append(c.Headers[name], v)
483				}
484			}
485			sort.Strings(c.HeaderLeaks)
486		}
487		if len(body) > 0 {
488			if json.Valid(body) {
489				c.Body = append(json.RawMessage(nil), body...)
490			} else {
491				c.RawBody = string(body)
492			}
493		}
494		d.captures = append(d.captures, c)
495	}
