 804	// oq3EnvelopeLeaks scans what a request carried besides its body: the decoded path, the query string's
 805	// keys and values decoded (and the raw query too), and the header scan made when the request arrived.
 806	func oq3EnvelopeLeaks(c oq3Capture) []string {
 807		out := oq3Leaks(c.Path)
 808		if c.Query != "" {
 809			out = append(out, oq3Leaks(c.Query)...)
 810			if q, err := url.ParseQuery(c.Query); err == nil {
 811				for k, vs := range q {
 812					out = append(out, oq3Leaks(k)...)
 813					for _, v := range vs {
 814						out = append(out, oq3Leaks(v)...)
 815					}
 816				}
 817			} else if u, err := url.QueryUnescape(c.Query); err == nil {
 818				out = append(out, oq3Leaks(u)...)
 819			}
 820		}
 821		for _, h := range c.HeaderLeaks {
 822			out = append(out, "header "+h)
 823		}
 824		return out
 825	}
